#!/bin/sh
# Production start, the image's CMD (generated by Shikshya): apply the committed migrations, then serve. It never
# installs packages and never makes migrations; previews run start.sh instead. It seeds only when SEED_DEMO=1, which
# Shikshya Cloud sets only when the Env tab asks, on an app's first deploy (then 0): the demo data and this app's
# sign-ins, loaded as start.sh loads them. Never set SEED_DEMO on a database with real users. With ADMIN_EMAIL
# and ADMIN_PASSWORD set it makes the owner's admin account once (PX.257).
set -eu
cd "$(dirname "$0")/.."
python manage.py migrate --noinput
if [ "${SEED_DEMO:-0}" = "1" ] && [ -f seed_data.json ] && [ -f seed_accounts.py ]; then
    SEED_STEP=before python manage.py shell < seed_accounts.py || echo "WARNING: the sign-up account was not made"
fi
if [ "${SEED_DEMO:-0}" = "1" ] && [ -f seed_data.json ]; then
    python manage.py loaddata seed_data.json || echo "WARNING: the seed data did not load"
fi
if [ "${SEED_DEMO:-0}" = "1" ] && [ -f seed_accounts.py ]; then
    python manage.py shell < seed_accounts.py || echo "WARNING: the sign-ins were not set up"
fi
if [ -n "${ADMIN_EMAIL:-}" ] && [ -n "${ADMIN_PASSWORD:-}" ] && [ -f seed_accounts.py ]; then
    SEED_STEP=admin python manage.py shell < seed_accounts.py || echo "WARNING: the admin account was not made"
fi
exec daphne --proxy-headers -b 0.0.0.0 -p "${PORT:-8000}" config.asgi:application
